select t.company_id, t.concept,
 (select count(*) from analytics.canonical_fact cf where cf.company_id=t.company_id and cf.canonical_concept_id=cc.id) n_cf,
 l.gap_reason, l.mapped_tags_filed, l.candidate_tags_filed, l.has_value
from t join analytics.canonical_concept cc on cc.name=t.concept
left join analytics.company_concept_lineage l on l.company_id=t.company_id and l.canonical_concept_id=cc.id